/* Hide the Starlight top navigation bar */
header.header {
	display: none;
}

/* Table formatting: vertical rule after the first column, zebra-striped rows */
.sl-markdown-content table :is(th, td):first-child {
	border-right: 1px solid var(--sl-color-gray-5);
}

.sl-markdown-content table tbody tr:nth-child(even) {
	background-color: color-mix(in srgb, var(--sl-color-gray-6) 40%, transparent);
}

